import{_ as t,o,c as d,a0 as s}from"./chunks/framework.CNXp-E7Q.js";const h=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),r={name:"explanation/architecture.md"};function a(n,e,c,i,l,u){return o(),d("div",null,[...e[0]||(e[0]=[s(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>bupha is a port/adapter monorepo. <code>bupha-core</code> holds the domain — the queue, <code>bupha.toml</code>, and the <code>Trigger</code>/<code>StatusSink</code> ports — and knows nothing about GitHub, dagger or cloudflared. Ports <code>bupha-runner</code> and <code>bupha-tunnel</code> each have impl crates; <code>bupha-github</code> implements both trigger (HMAC verify + push parse) and status sink. <code>bupha-cli</code> is the binary; <code>bupha-deploy</code> holds install-time helpers. <code>modules/dagger/</code> is the shared pipeline module (Python SDK) that <code>bupha init</code> installs into consumer repos.</p><p>The watcher pipeline:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /hook → HMAC (constant-time) → dedup X-GitHub-Delivery</span></span>
<span class="line"><span>  → route by repository.full_name → per-repo queue → one global</span></span>
<span class="line"><span>    worker → detached worktree → spawned runner child → status posts</span></span></code></pre></div><p>Key semantics:</p><ul><li><strong>latest-wins</strong> (default): at most 1 pending sha per repo; a newer push supersedes it and the skipped sha gets an honest &quot;error: superseded&quot; status. <code>queue = &quot;all&quot;</code> switches to bounded FIFO (32) for release-style repos that must run every push.</li><li><strong>cancel_running</strong>: kills the in-flight child on a new push — valid only with <code>latest</code> (rejected under <code>all</code>, which would drop a commit that was never superseded).</li><li><strong>Persistence</strong>: accepted work writes <code>queue.json</code> (tmp+rename) in <code>worktree.base</code>; a restart re-queues the interrupted <code>running</code> sha at the front.</li><li><strong>Ingress is decoupled</strong>: the listener binds localhost; a <code>Tunnel</code> child (<code>cloudflared</code> today) is supervised — reaped and respawned on exit. <code>direct</code>/<code>none</code> are for boxes already public.</li><li><strong>Secrets stay out of files</strong>: <code>secret_env</code>/<code>token_env</code> name env vars; the token reaches the runner only via the runner&#39;s own mechanism (e.g. <code>env://</code> secret for dagger).</li></ul><p>Design rule for extending: a new forge = a <code>Trigger</code>+<code>StatusSink</code> impl crate; a new pipeline = a <code>Runner</code> impl; a new ingress = a <code>Tunnel</code> impl. Core stays untouched.</p><p>One <strong>global worker</strong> serializes runs across every repo — a second push queues behind the in-flight job, it does not run in parallel. That is deliberate (one box, bounded resource use), not a hang: <code>journalctl --user -u bupha-watch</code> shows the queue moves.</p><h2 id="extension-seams-0-2-by-design-—-not-yet-ports" tabindex="-1">Extension seams (0.2+, by design — not yet ports) <a class="header-anchor" href="#extension-seams-0-2-by-design-—-not-yet-ports" aria-label="Permalink to &quot;Extension seams (0.2+, by design — not yet ports)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Coupling</th><th>Where</th><th>Planned port</th></tr></thead><tbody><tr><td>OS service mgmt</td><td><code>bupha-deploy</code> (systemd, df, journalctl)</td><td><code>Service</code> — launchd/Windows later</td></tr><tr><td>Secret storage</td><td><code>secret()</code> — env → secret-tool → file</td><td><code>keyring</code> crate backends (macOS/Win)</td></tr><tr><td>Config path</td><td><code>~/.config/bupha</code> (XDG)</td><td><code>dirs</code> crate for native paths</td></tr><tr><td>VCS ops</td><td><code>git()</code>/<code>repo_sync</code> in cli shell to git</td><td><code>Vcs</code> trait → <code>GitVcs</code> (jj/hg later)</td></tr><tr><td>Queue persistence</td><td><code>queue.json</code> load/save in cli</td><td><code>QueueStore</code> — SQLite/remote for distributed runners</td></tr></tbody></table>`,10)])])}const g=t(r,[["render",a]]);export{h as __pageData,g as default};
